<template><view class="page booking-page safe-bottom"><view v-if="service.serviceId" class="booking-service surface"><view class="mini-cover"><uni-icons type="home" size="28" color="#2e806d" /></view><view><text class="service-name">{{ service.serviceName }}</text><text class="price">¥{{ service.price }}/{{ service.unitName || '次' }}</text></view></view><view v-else class="empty-panel surface">{{ errorMessage || '服务不存在或已下架' }}</view><view v-if="service.serviceId" class="form-section surface"><text class="section-title">预约信息</text><text class="label">服务日期</text><picker mode="date" :value="form.date" :start="minDate" @change="form.date = $event.detail.value"><view class="picker-value">{{ form.date }}<uni-icons type="right" size="18" color="#9aa9a5" /></view></picker><text class="label">服务时段</text><view v-if="slots.length" class="slot-grid"><view v-for="slot in slots" :key="slot.slotId" class="slot" :class="{ active: form.slotId === slot.slotId }" @click="form.slotId = slot.slotId"><text>{{ slot.slotName }}</text><text class="slot-count">余{{ slot.availableCount ?? slot.maxReserve ?? '-' }}</text></view></view><view v-else class="muted">暂无可预约时段</view><text class="label">服务地址</text><view class="address-input" @click="chooseLocation"><text :class="{ muted: !form.address }">{{ form.address || '请选择服务地址' }}</text><uni-icons type="right" size="18" color="#9aa9a5" /></view><text class="label">联系电话</text><input v-model="form.phone" class="text-input" type="number" placeholder="请输入联系电话" maxlength="11" /><text class="label">备注（选填）</text><textarea v-model="form.remark" class="textarea" placeholder="告诉服务人员您的特殊需求" maxlength="120" /></view><view v-if="service.serviceId" class="submit-bar"><view><text class="total-label">应付金额</text><text class="total-price">¥{{ service.price }}</text></view><button class="primary-button" :loading="submitting" @click="submit">提交预约</button></view></view></template>
<script setup>
import { computed, onMounted, reactive, ref } from 'vue'; import uniIcons from '@dcloudio/uni-ui/lib/uni-icons/uni-icons.vue'; import { createOrder, getService, listSlots } from '@/api/service'; import { useAuthStore } from '@/stores/auth'
const authStore = useAuthStore(); const service = ref({}); const slots = ref([]); const submitting = ref(false); const errorMessage = ref(''); const today = new Date(); const minDate = computed(() => today.toISOString().slice(0, 10)); const form = reactive({ date: minDate.value, slotId: '', address: '', phone: authStore.user?.phonenumber || '', remark: '' })
function responseList (response) { return response?.rows || response?.data?.rows || (Array.isArray(response?.data) ? response.data : Array.isArray(response) ? response : []) }
onMounted(async () => { const id = getCurrentPages().at(-1)?.options?.id; try { const [serviceResponse, slotResponse] = await Promise.all([getService(id), listSlots({ serviceId: id })]); service.value = serviceResponse?.data || serviceResponse; slots.value = responseList(slotResponse); form.slotId = slots.value[0]?.slotId || '' } catch (e) { errorMessage.value = e.message || '预约信息加载失败' } })
function chooseLocation () { uni.chooseLocation({ success: result => { form.address = result.address || result.name } }) }
async function submit () { if (!authStore.isLoggedIn) return uni.navigateTo({ url: `/pages/login/index?redirect=${encodeURIComponent(`/pages/booking/index?id=${service.value.serviceId}`)}` }); if (!form.slotId) return uni.showToast({ title: '暂无可预约时段', icon: 'none' }); if (!form.address || !form.phone || !/^1\d{10}$/.test(form.phone)) return uni.showToast({ title: '请完善地址和手机号', icon: 'none' }); submitting.value = true; try { const response = await createOrder({ serviceId: service.value.serviceId, appointmentDate: form.date, slotId: form.slotId, address: form.address, phone: form.phone, remark: form.remark, amount: service.value.price }); uni.showToast({ title: '预约成功', icon: 'success' }); setTimeout(() => uni.redirectTo({ url: `/pages/order-detail/index?id=${response.data?.orderId || response.orderId || 'latest'}` }), 500) } catch (e) { uni.showToast({ title: e.message || '提交失败', icon: 'none' }) } finally { submitting.value = false } }
</script><style lang="scss" scoped>
.booking-page{padding-bottom:180rpx}.booking-service{display:flex;align-items:center;padding:24rpx}.mini-cover{display:flex;align-items:center;justify-content:center;width:100rpx;height:100rpx;border-radius:20rpx;background:$app-primary-soft}.booking-service>view:last-child{display:flex;flex-direction:column;margin-left:20rpx}.service-name{color:$app-text;font-size:30rpx;font-weight:700}.price{margin-top:10rpx;color:$app-accent;font-size:28rpx}.form-section{margin-top:20rpx;padding:30rpx}.label{display:block;margin-top:30rpx;margin-bottom:14rpx;color:$app-text;font-size:26rpx;font-weight:600}.picker-value,.address-input{display:flex;align-items:center;justify-content:space-between;padding:24rpx 0;color:$app-text;border-bottom:1rpx solid $app-border;font-size:28rpx}.muted{color:$app-muted}.slot-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14rpx}.slot{padding:18rpx 8rpx;text-align:center;border:1rpx solid $app-border;border-radius:12rpx;color:$app-text;font-size:24rpx}.slot.active{background:$app-primary-soft;border-color:#92c6b6;color:$app-primary}.slot-count{display:block;margin-top:6rpx;color:$app-muted;font-size:20rpx}.text-input,.textarea{width:100%;box-sizing:border-box;padding:22rpx 0;color:$app-text;border-bottom:1rpx solid $app-border;font-size:28rpx}.textarea{height:150rpx;padding:18rpx;border:1rpx solid $app-border;border-radius:12rpx}.submit-bar{position:fixed;right:0;bottom:0;left:0;z-index:10;display:flex;align-items:center;justify-content:space-between;padding:20rpx 32rpx calc(20rpx + env(safe-area-inset-bottom));background:#fff;border-top:1rpx solid $app-border}.total-label{display:block;color:$app-muted;font-size:22rpx}.total-price{display:block;margin-top:4rpx;color:$app-accent;font-size:36rpx;font-weight:800}.submit-bar .primary-button{width:280rpx;line-height:78rpx;font-size:28rpx}
</style>
